theorem PositionEncoding.stack_error_bound (E : PositionEncoding ι) {n : ℕ}
    (x y : Fin n → ι) (u v : Fin n → ℝ) {eps delta : ℝ}
    (huv : ∀ k, |u k - v k| ≤ eps) (hxy : ∀ k, E.distF (x k) (y k) ≤ delta)
    (hdelta : 0 ≤ delta) :
    |∑ k, (u k + E.phi (x k)) - ∑ k, (v k + E.phi (y k))|
      ≤ n * (eps + E.L * delta)
